mapper.select:
SELECT 
FROM tb_booking_request
WHERE status = #{status}
  AND next_publish_time <= #{now}
  AND result_event_state IN ('PENDING', 'PUBLISHED')
ORDER BY next_publish_time, id
LIMIT #{limit}

mapper.update:
UPDATE tb_booking_request
SET next_publish_time = #{next},
    result_publish_count = result_publish_count + 1,
    result_publish_token = #{token}
WHERE id = #{id}
  AND status IN ('SUCCEEDED', 'FAILED')
  AND result_event_state IN ('PENDING', 'PUBLISHED')
  AND next_publish_time <= #{now}

UPDATE tb_booking_request
SET result_event_state = 'PUBLISHED',
    result_last_publish_time = #{now}
WHERE id = #{id}
  AND result_publish_token = #{token}
  AND result_event_state IN ('PENDING', 'PUBLISHED')
